  ["4e1799ef28561854"] = { "I pesci al largo di Teldrassil sono piuttosto grossi e robusti. Si dice che la causa sia la rapida crescita del nostro nuovo albero del mondo.", "." },
  ["4e17c9e69d057d81"] = { "Trovi una cassetta della posta appena fuori dalla banca di ⟦Thunder Bluff=Picco del Tuono⟧, sul ripiano più basso.", "." },
  ["4e1b76e5f50533af"] = { "Le caverne sono state purificate. Andiamo alla camera di Naralex!", "." },
  ["4e1cc5e4cf6702a6"] = { "Tragico...", "." },
  ["4e1ceceb91630f2d"] = { "È passato troppo tempo. Dobbiamo riprovare più tardi.", "." },
  ["4e21dce54520ce4a"] = { "Salute, {name}. Ci siamo già incontrati? Hai un'aria vagamente familiare.", "." },
  ["4e2afc6b23754081"] = { "Posso mostrarti ciò che desideri sapere, ma devi avere pazienza. Prenditi il tempo di lavorare l'acciaio e di sentire come prende forma sotto il tuo martello. Quando diventerai tutt'uno con l'acciaio, allora capirai.", "." },
  ["4e327bef67a4cbbc"] = { "Cerco addestramento da druido.", "." },
  ["4e34684cde53714f"] = { "Sia lodato Egan!", "." },
  ["4e3bb93a6c74f863"] = { "Ci servono avventurieri che ci aiutino, {name}. Ci aiuterai?", "." },
  ["4e4f86b7669c3cee"] = { "L'istruttore dei cacciatori si chiama Thotar. Cercalo dentro la tana nell'angolo sud-ovest di ⟦Razor Hill=Tranciacolle⟧.", "." },
  ["4e5d3804b8530835"] = { "Darianna promette bene, ma ha così tanta energia che fatica a stare ferma ad ascoltare. Con la sua forza e la sua agilità, temo che non passerà molto prima che venga chiamata a combattere. Dobbiamo istruirla in fretta.", "." },
  ["4e5e67ddfa4e8762"] = { "È ora che tu ti unisca a noi, {class}.", "." },
  ["4e6d648598cd04a8"] = { "Banca di ⟦Ironforge=Forgiardente⟧", "." },
  ["4e6e95dc719dc1d5"] = { "Di recente ho avuto un brutto incontro con alcuni dei Defias da queste parti, ma Michelle Belle mi ha rimesso in sesto per bene. Chiedi a lei, alla Locanda del Fiero Leone, e vedi se ti insegna.", "." },
  ["4e733c0fa71de317"] = { "Non credo che tu voglia imparare qualcosa che posso insegnarti. Faresti meglio a cercare un istruttore di {class} che ti aiuti.", "." },
  ["4e7486cb0640e50d"] = { "Fate largo! Lasciateli passare!", "." },
  ["4e75b2cecea6222c"] = { "Sei qui per imparare? Molto bene. Immagino che, se ti istruisco, non potrai fare molto male ai nostri alleati. Basta che tu riesca davvero a fare male ai nostri nemici.", "." },
  ["4e833f4d3decb2f7"] = { "Vorrei inserire il mio codice e-coupon per vincere l'oggetto virtuale.", "." },
  ["4e84e824ec48da20"] = { "AIUTO! SONO VENUTI DEGLI ASSASSINI A UCCIDERMI!", "." },
  ["4e86aee35427155d"] = { "Credo che agli spiriti tu piaccia più di me: io non ho ancora sentito il loro richiamo, ma tu sembri aver appreso bene le loro lezioni. Va' a parlare con Karn, sarà entusiasta di vedere qualcuno che li sente come lui.", "." },
  ["4e87199aee0907bc"] = { "Defias? Non va bene. Non va affatto bene. Ti prego, continua.", "." },
  ["4e8b8baa35f6d085"] = { "Da quando siamo qui nel cratere, Dadanga ha preso gusto ai grossi Germogli di Petalorosso che crescono un po' ovunque.\n\nDi sicuro gradirebbe uno spuntino, se ti va di portargliene qualcuno...", "." },
  ["4e961e9ec9242730"] = { "Le forze del Re dei Lich si stanno ammassando. È fondamentale che la nostra tabella di marcia sostenga i suoi piani.", "." },
  ["4e9661c650135aef"] = { "Bravo! Bravo! Bello spettacolo. Cosa? Credevi che fosse finita per me?", "." },
  ["4e9b7b7d6ccd85fd"] = { "Ora vi lascio, mortali. Vivi e con questi ninnoli. Maltrake! Presenta loro i ninnoli!", "." },
  ["4ea9731e3bf1ba26"] = { "La ⟦Soul Gem=Gemma dell'Anima⟧ lascia %s senza parole!", "." },
  ["4eafd0be7d13befd"] = { "Tra la luce e il buio c'è l'ombra... e quelle ombre hanno poteri che devi ancora vedere.", "." },
  ["4eb869a4cbe0e79c"] = { "Lord sindaco! I nostri esploratori segnalano strane attività a ovest.", "." },
  ["4ec8d2055e2664f3"] = { "Non troverai un maestro dei grifoni in un posto qualsiasi di Dun Morogh, <ragazzo/ragazza>. Dovrai andare a ⟦Ironforge=Forgiardente⟧ se vuoi prendere un grifone per andare da qualche parte.", "." },
  ["4ecbee4d728ce97d"] = { "%s ruggisce chiamando il suo compagno!", "." },
  ["4ecea2976c43fe16"] = { "Il capitano al momento è impegnato. Sta studiando delle mappe degli alveari sotterranei dei silitidi che abbiamo ottenuto di recente. Resta con noi se vuoi aiutare: uscirà da un momento all'altro.", "." },
  ["4ed1012a83812b9d"] = { "Maestro dei pipistrelli", "." },
  ["4ee537962c9b565e"] = { "Malvagi, malvagi mortali! La foresta piange. Gli elementi si ritraggono davanti alla distruzione. Ivus deve cancellarvi da questo mondo!", "." },
  ["4eff183a32c74734"] = { "Ehi, tu! Hai l'aria di chi è in forze... ci serve il tuo aiuto per difendere ⟦Southshore=Riva del Sud⟧!\n\nQuei maledetti Reietti sono tutti agitati perché è la Veglia delle Ombre. La loro «festa» li porterà dritti alla nostra porta, poco ma sicuro. Se hai tempo, il tuo aiuto ci farebbe davvero comodo!", "." },
